function reviewCard(r,isExample=false){return `<article class="review-card" aria-label="${isExample?'Illustrative review example, not genuine customer feedback':'Genuine customer review'}"><div class="review-card-top"><span class="review-stars" aria-label="${Number(r.rating)||5} out of five stars">${'★'.repeat(Number(r.rating)||5)}${'☆'.repeat(Math.max(0,5-(Number(r.rating)||5)))}</span></div><blockquote>“${esc(r.text)}”</blockquote><div class="review-person"><strong>${esc(r.author)}</strong><span>${esc(r.location||'Nigeria')}</span></div></article>`}
function reviewsSection(){const published=(db.reviews||[]).filter(r=>r.visible&&r.consent);const demo=!published.length;const arr=demo?SAMPLE_REVIEW_COPY:published;const group=arr.map(r=>reviewCard(r,demo)).join('');return `<section class="reviews-section" aria-labelledby="reviews-heading"><div class="review-heading"><h2 id="reviews-heading">Review</h2></div><div class="review-track-window" id="review-track-window" tabindex="0" aria-label="${demo?'Illustrative review examples':'Customer reviews'}; swipe sideways to browse"><div class="review-track">${[0,1,2].map((x)=>`<div class="review-track-group" ${x===1?'':'aria-hidden="true"'}>${group}</div>`).join('')}</div></div></section>`}
let gdsbReviewAnimationFrame=0;
function initReviewCarousel(){
  if(gdsbReviewAnimationFrame&&window.cancelAnimationFrame)window.cancelAnimationFrame(gdsbReviewAnimationFrame);
  gdsbReviewAnimationFrame=0;
  const scroller=document.getElementById('review-track-window');if(!scroller)return;
  const group=scroller.querySelector('.review-track-group');if(!group)return;
  const groupWidth=()=>group.getBoundingClientRect().width;
  const width=groupWidth();if(!width)return;
  scroller.scrollLeft=width;
  let dragging=false,touching=false,mouseStartX=0,mouseStartLeft=0;
  function recenter(){const w=groupWidth();if(!w)return;const n=scroller.scrollLeft;
    if(n<w*.5)scroller.scrollLeft=n+w;
    else if(n>w*1.5)scroller.scrollLeft=n-w;
  }
  scroller.addEventListener('touchstart',()=>{touching=true},{passive:true});
  scroller.addEventListener('touchend',()=>{touching=false;recenter()},{passive:true});
  scroller.addEventListener('touchcancel',()=>{touching=false;recenter()},{passive:true});
  scroller.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;dragging=true;mouseStartX=e.clientX;mouseStartLeft=scroller.scrollLeft;scroller.classList.add('dragging')});
  scroller.addEventListener('pointermove',e=>{if(!dragging||e.pointerType!=='mouse')return;scroller.scrollLeft=mouseStartLeft-(e.clientX-mouseStartX);recenter()});
  for(const eventName of ['pointerup','pointercancel','pointerleave'])scroller.addEventListener(eventName,()=>{dragging=false;scroller.classList.remove('dragging');recenter()});
  scroller.addEventListener('keydown',e=>{if(e.key!=='ArrowRight'&&e.key!=='ArrowLeft')return;e.preventDefault();scroller.scrollLeft+=(e.key==='ArrowRight'?1:-1)*200;recenter()});
  if(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches)return;
  if(typeof window.requestAnimationFrame!=='function')return;
  let previous=0;
  function tick(time){
    if(previous&&time>previous&&!dragging&&!touching&&!document.hidden){
      const dt=Math.min((time-previous)/1000,.1);
      scroller.scrollLeft+=dt*86;
      recenter();
    }
    previous=time;
    gdsbReviewAnimationFrame=window.requestAnimationFrame(tick);
  }
  gdsbReviewAnimationFrame=window.requestAnimationFrame(tick);
}
function reviewsAdmin(){const reviews=db.reviews||[];return `<section class="card admin-form-card"><h2 class="admin-panel-title">Customer reviews</h2><p class="muted">Add genuine customer feedback only with permission to publish it.</p><form onsubmit="saveReview(event)"><div class="form-grid"><div class="form-field"><label>Customer display name *</label><input name="author" required maxlength="60" placeholder="e.g. First name or Anonymous"></div><div class="form-field"><label>Location (optional)</label><input name="location" maxlength="60" placeholder="e.g. Osun"></div><div class="form-field"><label>Rating *</label><select name="rating"><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option><option value="2">2 stars</option><option value="1">1 star</option></select></div></div><div class="form-field"><label>Customer's actual words *</label><textarea name="text" maxlength="480" required placeholder="Paste the real review here. Do not add medical claims that haven't been verified."></textarea></div><label class="review-consent-label"><input type="checkbox" name="consent" required> I confirm this is genuine feedback and the customer has agreed to its publication.</label><button class="btn btn-primary" type="submit">Add review</button></form><hr class="section-rule"><h3>Saved reviews (${reviews.length})</h3>${reviews.length?reviews.map(r=>`<div class="review-admin-row"><div><b>${esc(r.author)}</b><small>${esc(r.location||'Nigeria')} · ${r.rating} stars · ${r.visible?'Shown':'Hidden'}</small><p>${esc(r.text)}</p></div><div class="review-admin-actions"><button class="mini-btn" onclick="toggleReview('${r.id}')">${r.visible?'Hide':'Show'}</button><button class="mini-btn danger" onclick="deleteReview('${r.id}')">Delete</button></div></div>`).join(''):'<p class="muted">No genuine customer reviews have been added yet.</p>'}</section>`}
function saveReview(e){e.preventDefault();const f=new FormData(e.target);if(!f.has('consent'))return toast('Confirm customer permission first');const text=String(f.get('text')||'').trim(),author=String(f.get('author')||'').trim();if(!text||!author)return toast('Fill in the reviewer name and review');db.reviews=db.reviews||[];db.reviews.unshift({id:'rv'+Date.now(),author,location:String(f.get('location')||'').trim(),rating:Math.min(5,Math.max(1,Number(f.get('rating')||5))),text,visible:true,consent:true});save();render();toast('Customer review added')}
function toggleReview(id){const r=(db.reviews||[]).find(r=>r.id===id);if(!r)return;r.visible=!r.visible;save();render()}
function deleteReview(id){if(!confirm('Permanently delete this review?'))return;db.reviews=(db.reviews||[]).filter(r=>r.id!==id);save();render();toast('Review deleted')}

function checkoutStepper(stage){const delivery=stage==='delivery';return `<div class="checkout-stepper" aria-label="Checkout progress"><div class="checkout-step ${delivery?'active':'done'}"><span class="step-circle">${delivery?'1':icon('check')}</span><strong>Delivery</strong></div><span class="step-connector" aria-hidden="true"></span><div class="checkout-step ${!delivery?'active':''}"><span class="step-circle">2</span><strong>Payment</strong></div></div>`}
function checkoutActionBar(stage){if(stage==='delivery')return `<div class="checkout-action-bar"><button type="button" class="checkout-back" onclick="nav('cart')">${icon('back')} Back</button><button type="submit" form="delivery-form" class="checkout-next">Continue to payment ${icon('arrow')}</button></div>`;return `<div class="checkout-action-bar"><button type="button" class="checkout-back" onclick="nav('checkout')">${icon('back')} Back</button><button type="submit" form="payment-form" class="checkout-next">${icon('check')} Submit payment & order</button></div>`}
async function copyPayment(value){try{await navigator.clipboard.writeText(String(value));toast('Copied to clipboard')}catch{toast('Please select and copy manually')}}
function copyBtn(text){return `<button type="button" class="payment-copy" data-copy="${esc(text)}" onclick="copyPayment(this.dataset.copy)">${icon('copy')} Copy</button>`}
function orderReference(){let id=sessionStorage.getItem('gdsb_pending_order');if(!id){id='GD-'+String(Date.now()).slice(-8);sessionStorage.setItem('gdsb_pending_order',id)}return id}

if(page==='admin'&&location.hash){adminTab=location.hash.slice(1)||'overview'}setInterval(updateTimer,1000);if(!window.GDSB_EXPECT_BACKEND)render();if(page==='shop'&&sessionStorage.getItem('gdsb_focus_search')){sessionStorage.removeItem('gdsb_focus_search');document.querySelector('#shop-search')?.focus()}
